"""Retain one bounded, read-only ITM study status observation (no submissions)."""

from __future__ import annotations

import argparse
import datetime as dt
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import tempfile
from zoneinfo import ZoneInfo


MAX_JSON_BYTES = 32 * 1024 * 1024
SECRET_KEY = re.compile(r"password|secret|token|credential|authorization|access.?key", re.I)
SHA = re.compile(r"[0-9a-f]{40}")


def safe(value):
    if isinstance(value, dict):
        return {key: "<redacted>" if SECRET_KEY.search(str(key)) else safe(item) for key, item in value.items()}
    if isinstance(value, list):
        return [safe(item) for item in value]
    if isinstance(value, str):
        value = re.sub(r"(://)[^/@\s]+:[^/@\s]+@", r"\1<redacted>@", value)
        value = re.sub(r"(?i)(password|token|secret|authorization|credential)\s*[=:]\s*\S+", r"\1=<redacted>", value)
        value = re.sub(r"\b(?:AKIA|ASIA)[A-Z0-9]{16}\b", "<redacted>", value)
    return value


def read_json(path):
    if path.stat().st_size > MAX_JSON_BYTES:
        raise ValueError("JSON exceeds bounded snapshot read limit")
    return json.loads(path.read_text(encoding="utf-8"))


def command(argv):
    try:
        result = subprocess.run(argv, capture_output=True, text=True, timeout=25, check=False)
        return {"argv": argv, "returncode": result.returncode,
                "stdout": safe(result.stdout[-64000:]), "stderr": safe(result.stderr[-8000:])}
    except (OSError, subprocess.TimeoutExpired) as error:
        return {"argv": argv, "error": safe(str(error))}


def artifact_ref(records, identity):
    record = records.get(identity, {})
    return {key: record[key] for key in ("id", "uri", "sha256", "size_bytes", "role") if key in record}


def attempt_status(directory):
    terminal = directory / "terminal.json"
    snapshot = terminal if terminal.is_file() else directory / "current.json"
    rows = read_json(snapshot)
    records = {record["id"]: record for record in rows}
    attempt = next(record for record in rows if record.get("kind") == "attempt")
    facts = attempt.get("facts", {})
    checkpoints = []
    for key, fact in facts.items():
        match = re.fullmatch(r"checkpoint_(\d+)", key)
        if match:
            checkpoint = fact.get("value", {})
            checkpoints.append({"environment_steps": int(match.group(1)),
                "artifacts": {name: artifact_ref(records, checkpoint.get(name))
                              for name in ("model", "sidecar", "training_state") if checkpoint.get(name)}})
    checkpoints.sort(key=lambda value: value["environment_steps"])
    updates = list((directory / "updates").glob("*.json"))
    latest = max(updates, key=lambda path: int(path.stem) if path.stem.isdigit() else -1) if updates else None
    result = {"id": attempt["id"], "trial_id": attempt.get("trial_id"),
        "status": attempt.get("status"), "budgets": attempt.get("budgets"),
        "snapshot": str(snapshot), "snapshot_mtime": snapshot.stat().st_mtime,
        "checkpoint_count": len(checkpoints), "latest_checkpoints": checkpoints[-2:],
        "source_revision": facts.get("source_revision", {}).get("value"),
        "training_cost": facts.get("training_cost", {}).get("value"),
        "latest_update": read_json(latest) if latest else None}
    if "error" in attempt:
        result["error"] = attempt["error"]
    for key in ("failure", "execution_error", "exception"):
        if key in facts:
            result[key] = facts[key]
    return safe(result)


def log_tail(path):
    with path.open("rb") as stream:
        stream.seek(max(0, path.stat().st_size - 64000))
        lines = stream.read().decode("utf-8", errors="replace").splitlines()
    selected = [line for line in lines if re.search(
        r"error|traceback|fail|exception|training|step|sps|remaining|restored|attempt_id|evidence_root|slurmstepd|cancel|killed",
        line, re.I)]
    return {"path": str(path), "mtime": path.stat().st_mtime, "size_bytes": path.stat().st_size,
            "relevant_tail": safe(selected[-40:])}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--study-root", required=True, type=Path)
    parser.add_argument("--job-id", action="append", type=int, help="Defaults to production jobs 4128 and 4129")
    args = parser.parse_args()
    root = args.study_root.resolve(strict=True)
    if not root.is_dir():
        parser.error("study-root must be an existing directory")
    now = dt.datetime.now(ZoneInfo("America/New_York"))
    output = root / "checkins" / "evening-20261107.json"
    if output.exists():
        parser.error(f"Immutable check-in already exists: {output}")
    result = {"schema_version": 1, "observed_at": now.isoformat(),
        "observed_at_utc": now.astimezone(dt.timezone.utc).isoformat(), "study_root": str(root),
        "collector_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "meaning": "One status observation; missing/failed reads are retained, not inferred as success.",
        "job_files": [], "attempts": [], "summaries": [], "logs": [], "read_errors": []}
    jobs = set(args.job_id or (4128, 4129))
    for path in sorted((root / "logs").glob("*.job")):
        try:
            content = path.read_text(encoding="utf-8")[:256].strip()
            ids = [int(value) for value in re.findall(r"\b\d{3,10}\b", content)]
            jobs.update(ids)
            result["job_files"].append({"path": str(path), "job_ids": ids})
        except (OSError, ValueError) as error:
            result["read_errors"].append({"path": str(path), "error": str(error)})
    job_list = ",".join(str(job) for job in sorted(jobs))
    result["scheduler"] = {
        "squeue": command(["squeue", "-h", "-j", job_list, "-o", "%i|%T|%M|%l|%C|%b|%R"]),
        "sacct": command(["sacct", "-n", "-P", "-j", job_list,
                          "--format=JobIDRaw,JobName,State,ExitCode,Elapsed,Start,End,AllocCPUS,AllocTRES"]),
    }
    for directory in sorted((root / "evidence" / "attempts").glob("*")):
        if not directory.is_dir():
            continue
        try:
            result["attempts"].append(attempt_status(directory))
        except (OSError, ValueError, KeyError, StopIteration, TypeError) as error:
            result["read_errors"].append({"path": str(directory), "error": str(error)})
    result["source_revisions"] = sorted({attempt["source_revision"] for attempt in result["attempts"]
                                        if isinstance(attempt.get("source_revision"), str)
                                        and SHA.fullmatch(attempt["source_revision"])})
    result["source_pin"] = result["source_revisions"][0] if len(result["source_revisions"]) == 1 else None
    # Read only named reports, avoiding source, input banks and large evidence/runtime trees.
    report_names = {"summary.json", "validation.json", "smoke-validation.json", "smoke-resume-validation.json"}
    visited = 0
    for parent, dirs, files in os.walk(root):
        dirs[:] = [name for name in dirs if name not in {
            "evidence", "inputs", "runtime", "outputs", "source", ".venv", ".git", "checkins", "logs"}]
        visited += 1
        if visited > 300:
            result["read_errors"].append({"path": str(root), "error": "Report scan stopped at 300 directories"})
            break
        for name in files:
            if name not in report_names and not (name.endswith(".json") and ("summary" in name or "validation" in name)):
                continue
            path = Path(parent) / name
            try:
                result["summaries"].append({"path": str(path), "mtime": path.stat().st_mtime,
                                             "value": safe(read_json(path))})
            except (OSError, ValueError) as error:
                result["read_errors"].append({"path": str(path), "error": str(error)})
    for path in sorted((root / "logs").glob("*")):
        if not path.is_file() or path.suffix not in {".out", ".err", ".log"}:
            continue
        try:
            result["logs"].append(log_tail(path))
        except OSError as error:
            result["read_errors"].append({"path": str(path), "error": str(error)})
    result = safe(result)
    output.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=output.parent, delete=False) as stream:
            temporary = Path(stream.name)
            json.dump(result, stream, indent=2, sort_keys=True, allow_nan=False)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary, output)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    print(json.dumps({"snapshot": str(output), "observed_at": now.isoformat(),
                      "attempts": len(result["attempts"]), "read_errors": len(result["read_errors"])}))


if __name__ == "__main__":
    main()

